from dataclasses import dataclass
from datetime import datetime, timezone
import math


def utc(dt):
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


@dataclass(frozen=True)
class Event:
    source: str
    series: str
    valid_at: datetime
    available_at: datetime
    value: float
    unit: str = ""
    run_at: datetime | None = None
    lead_minutes: int | None = None

    def __post_init__(self):
        object.__setattr__(self, "valid_at", utc(self.valid_at))
        object.__setattr__(self, "available_at", utc(self.available_at))
        if self.run_at is not None:
            object.__setattr__(self, "run_at", utc(self.run_at))


class EventStore:
    """Append-only event store with separate publication and validity clocks."""

    def __init__(self):
        self._events = []

    def append(self, event):
        self._events.append(event)

    def extend(self, events):
        self._events.extend(events)

    def as_of(self, decision_time, source=None, series=None,
              valid_at_lte=None, valid_at_gte=None):
        t = utc(decision_time)
        hi = utc(valid_at_lte) if valid_at_lte is not None else None
        lo = utc(valid_at_gte) if valid_at_gte is not None else None
        out = []
        for event in self._events:
            if event.available_at > t:
                continue
            if source is not None and event.source != source:
                continue
            if series is not None and event.series != series:
                continue
            if hi is not None and event.valid_at > hi:
                continue
            if lo is not None and event.valid_at < lo:
                continue
            out.append(event)
        out.sort(key=lambda e: (e.valid_at, e.available_at))
        return out

    def latest(self, decision_time, source=None, series=None):
        values = self.as_of(decision_time, source=source, series=series)
        return values[-1] if values else None

    def latest_observed(self, decision_time, source=None, series=None):
        """Latest value that was both published and valid by decision_time."""
        values = self.as_of(
            decision_time, source=source, series=series,
            valid_at_lte=decision_time,
        )
        return values[-1] if values else None

    def future_available(self, decision_time, source=None, series=None):
        """Forecast/future-valid values already published by decision_time."""
        return self.as_of(
            decision_time, source=source, series=series,
            valid_at_gte=decision_time,
        )

    def clear_source(self, source):
        self._events = [e for e in self._events if e.source != source]

    def __len__(self):
        return len(self._events)


def power_mean(values, p):
    values = [max(float(v), 1e-9) for v in values]
    if not values:
        raise ValueError("power_mean requires at least one value")
    n = float(len(values))
    if abs(p) < 1e-12:
        return math.exp(sum(math.log(v) for v in values) / n)
    if p < 0 and any(v <= 0 for v in values):
        raise ValueError("negative p requires positive values")
    return (sum(v ** p for v in values) / n) ** (1.0 / p)


class VirtualBattery:
    """Small non-grid-impacting battery used purely as an action surface."""

    def __init__(self, capacity_kwh=20.0, max_kw=5.0, soc_kwh=10.0,
                 eta_charge=0.95, eta_discharge=0.95):
        self.capacity_kwh = float(capacity_kwh)
        self.max_kw = float(max_kw)
        self.soc_kwh = float(soc_kwh)
        self.eta_charge = float(eta_charge)
        self.eta_discharge = float(eta_discharge)

    def clone(self):
        return VirtualBattery(
            self.capacity_kwh,
            self.max_kw,
            self.soc_kwh,
            self.eta_charge,
            self.eta_discharge,
        )

    def step(self, action_kw, price_eur_mwh, dt_hours=0.25):
        action_kw = max(-self.max_kw, min(self.max_kw, float(action_kw)))
        old_soc = self.soc_kwh
        if action_kw >= 0:
            delta = action_kw * dt_hours * self.eta_charge
        else:
            delta = action_kw * dt_hours / self.eta_discharge
        requested_soc = old_soc + delta
        self.soc_kwh = max(0.0, min(self.capacity_kwh, requested_soc))
        grid_energy_mwh = action_kw * dt_hours / 1000.0
        cash_cost = grid_energy_mwh * float(price_eur_mwh)
        violation = abs(requested_soc - self.soc_kwh)
        return cash_cost, violation

import math


class CubicSplineEdge:
    """Small inspectable cubic Hermite spline edge.

    Values live on fixed x knots. Tangents are finite differences, which keeps
    the edge easy to display and differentiate without third-party packages.
    """

    def __init__(self, knots, values):
        if len(knots) != len(values) or len(knots) < 3:
            raise ValueError("knots and values must have the same length >= 3")
        self.knots = [float(x) for x in knots]
        self.values = [float(y) for y in values]

    def _segment(self, x):
        if x <= self.knots[0]:
            return 0
        if x >= self.knots[-1]:
            return len(self.knots) - 2
        for i in range(len(self.knots) - 1):
            if self.knots[i] <= x <= self.knots[i + 1]:
                return i
        return len(self.knots) - 2

    def _tangent(self, i):
        if i == 0:
            dx = self.knots[1] - self.knots[0]
            return (self.values[1] - self.values[0]) / dx
        if i == len(self.knots) - 1:
            dx = self.knots[-1] - self.knots[-2]
            return (self.values[-1] - self.values[-2]) / dx
        dx = self.knots[i + 1] - self.knots[i - 1]
        return (self.values[i + 1] - self.values[i - 1]) / dx

    def value(self, x):
        i = self._segment(float(x))
        x0, x1 = self.knots[i], self.knots[i + 1]
        y0, y1 = self.values[i], self.values[i + 1]
        h = x1 - x0
        if h <= 0:
            raise ValueError("knots must be strictly increasing")
        u = max(0.0, min(1.0, (float(x) - x0) / h))
        m0, m1 = self._tangent(i), self._tangent(i + 1)
        h00 = 2*u**3 - 3*u**2 + 1
        h10 = u**3 - 2*u**2 + u
        h01 = -2*u**3 + 3*u**2
        h11 = u**3 - u**2
        return h00*y0 + h10*h*m0 + h01*y1 + h11*h*m1

    def derivative(self, x, eps=1e-4):
        return (self.value(x + eps) - self.value(x - eps)) / (2 * eps)

    def second_derivative(self, x, eps=1e-3):
        return (self.value(x + eps) - 2*self.value(x) + self.value(x - eps)) / (eps*eps)


class KANEnergy:
    """Minimal additive KAN-style scalar energy.

    Each state coordinate passes through an inspectable learned-style spline.
    Cross-coordinate composition comes later; this version is deliberately tiny
    enough to debug in the HUD.
    """

    def __init__(self):
        k = [-1.5, -0.75, 0.0, 0.75, 1.5]
        self.edges = [
            CubicSplineEdge(k, [0.35, 0.05, -0.10, 0.08, 0.42]),
            CubicSplineEdge(k, [0.30, 0.02, -0.08, 0.04, 0.38]),
            CubicSplineEdge(k, [0.18, 0.04, -0.04, 0.06, 0.22]),
        ]
        self.weights = [0.9, 1.1, 0.6]

    def energy(self, state, conditioning=None):
        conditioning = conditioning or {}
        wind_push = 0.10 * float(conditioning.get("wind", 0.0))
        solar_push = -0.08 * float(conditioning.get("solar", 0.0))
        result = sum(w * e.value(x) for w, e, x in zip(self.weights, self.edges, state))
        return result + wind_push * state[0] + solar_push * state[2]

    def gradient(self, state, conditioning=None):
        conditioning = conditioning or {}
        grad = [w * e.derivative(x) for w, e, x in zip(self.weights, self.edges, state)]
        grad[0] += 0.10 * float(conditioning.get("wind", 0.0))
        grad[2] -= 0.08 * float(conditioning.get("solar", 0.0))
        return grad


class HopfieldEnergy:
    def __init__(self, memories=None, beta=3.0):
        self.memories = memories or [
            [-0.75, -0.55, 0.80],   # renewable surplus
            [0.10, 0.05, 0.05],     # ordinary transition
            [0.75, 0.85, -0.65],    # scarcity / expensive residual load
        ]
        self.beta = float(beta)

    def _logsumexp(self, values):
        m = max(values)
        return m + math.log(sum(math.exp(v - m) for v in values))

    def _weights(self, state):
        logits = [self.beta * sum(a*b for a, b in zip(memory, state))
                  for memory in self.memories]
        m = max(logits)
        raw = [math.exp(v - m) for v in logits]
        total = sum(raw)
        return [v / total for v in raw]

    def energy(self, state):
        norm = 0.5 * sum(x*x for x in state)
        logits = [self.beta * sum(a*b for a, b in zip(memory, state))
                  for memory in self.memories]
        return norm - self._logsumexp(logits) / self.beta

    def gradient(self, state):
        weights = self._weights(state)
        mean_memory = [0.0] * len(state)
        for w, memory in zip(weights, self.memories):
            for i, value in enumerate(memory):
                mean_memory[i] += w * value
        return [x - m for x, m in zip(state, mean_memory)]


class CombinedLandscape:
    def __init__(self, hopfield=None, kan=None, lambda_kan=0.65):
        self.hopfield = hopfield or HopfieldEnergy()
        self.kan = kan or KANEnergy()
        self.lambda_kan = float(lambda_kan)

    def energy(self, state, conditioning=None):
        return self.hopfield.energy(state) + self.lambda_kan * self.kan.energy(state, conditioning)

    def gradient(self, state, conditioning=None):
        gh = self.hopfield.gradient(state)
        gk = self.kan.gradient(state, conditioning)
        return [a + self.lambda_kan*b for a, b in zip(gh, gk)]

    def relax(self, state, conditioning=None, steps=80, rate=0.08):
        x = [float(v) for v in state]
        for _ in range(steps):
            grad = self.gradient(x, conditioning)
            x = [max(-1.6, min(1.6, a - rate*g)) for a, g in zip(x, grad)]
        return x

    def basin(self, state, conditioning=None):
        x = self.relax(state, conditioning)
        best = None
        best_dist = None
        for i, memory in enumerate(self.hopfield.memories):
            dist = sum((a-b)**2 for a, b in zip(x, memory))
            if best_dist is None or dist < best_dist:
                best = i
                best_dist = dist
        return best, x

    def directional_curvature(self, state, direction, conditioning=None, eps=1e-3):
        norm = math.sqrt(sum(v*v for v in direction)) or 1.0
        d = [v / norm for v in direction]
        plus = [x + eps*v for x, v in zip(state, d)]
        minus = [x - eps*v for x, v in zip(state, d)]
        e0 = self.energy(state, conditioning)
        return (self.energy(plus, conditioning) - 2*e0 + self.energy(minus, conditioning)) / (eps*eps)

