def _utc(dt):
    return utc(dt)


def _parse_time(value):
    return _utc(datetime.fromisoformat(str(value).replace("Z", "+00:00")))


class SMARDClient:
    BASE = "https://www.smard.de/app/chart_data"

    def __init__(self, fetch_json):
        self.fetch_json = fetch_json

    @staticmethod
    def index_url(filter_id, region="DE", resolution="quarterhour"):
        return "%s/%s/%s/index_%s.json" % (
            SMARDClient.BASE, int(filter_id), region, resolution
        )

    @staticmethod
    def series_url(filter_id, timestamp_ms, region="DE", resolution="quarterhour"):
        f = int(filter_id)
        return "%s/%s/%s/%s_%s_%s_%s.json" % (
            SMARDClient.BASE, f, region, f, region, resolution, int(timestamp_ms)
        )

    def available_blocks(self, filter_id, region="DE", resolution="quarterhour"):
        payload = self.fetch_json(self.index_url(filter_id, region, resolution))
        return list(payload.get("timestamps", []))

    def fetch_block(self, filter_id, timestamp_ms, region="DE", resolution="quarterhour", fetched_at=None):
        fetched_at = _utc(fetched_at or datetime.now(timezone.utc))
        payload = self.fetch_json(self.series_url(filter_id, timestamp_ms, region, resolution))
        created_ms = payload.get("meta_data", {}).get("created")
        if created_ms is not None:
            available_at = datetime.fromtimestamp(created_ms / 1000.0, tz=timezone.utc)
        else:
            available_at = fetched_at
        out = []
        for row in payload.get("series", []):
            if not row or len(row) < 2 or row[1] is None:
                continue
            valid_at = datetime.fromtimestamp(row[0] / 1000.0, tz=timezone.utc)
            out.append((valid_at, available_at, float(row[1])))
        return out

    def events(self, name, timestamp_ms, region="DE", resolution="quarterhour", unit="", fetched_at=None):
        return [
            Event("smard", name, valid_at, available_at, value, unit)
            for valid_at, available_at, value in self.fetch_block(
                SMARD_FILTERS[name], timestamp_ms, region=region,
                resolution=resolution, fetched_at=fetched_at,
            )
        ]


async def browser_fetch_json(url):
    """Fetch JSON through Pyodide's browser fetch path."""
    try:
        from pyodide.http import pyfetch
    except Exception as exc:
        raise RuntimeError("browser fetch is only available inside DVX/Pyodide") from exc
    response = await pyfetch(str(url), method="GET")
    if not response.ok:
        raise RuntimeError("HTTP %s for %s" % (response.status, url))
    return await response.json()


class AsyncSMARDClient:
    BASE = SMARDClient.BASE

    def __init__(self, fetch_json=browser_fetch_json):
        self.fetch_json = fetch_json

    async def latest_events(self, name, unit="", fetched_at=None):
        fetched_at = _utc(fetched_at or datetime.now(timezone.utc))
        filter_id = SMARD_FILTERS[name]
        index = await self.fetch_json(SMARDClient.index_url(filter_id))
        blocks = list(index.get("timestamps", []))
        if not blocks:
            raise RuntimeError("SMARD has no blocks for %s" % name)
        timestamp_ms = blocks[-1]
        payload = await self.fetch_json(SMARDClient.series_url(filter_id, timestamp_ms))
        created_ms = payload.get("meta_data", {}).get("created")
        available_at = (
            datetime.fromtimestamp(created_ms / 1000.0, tz=timezone.utc)
            if created_ms is not None else fetched_at
        )
        out = []
        for row in payload.get("series", []):
            if not row or len(row) < 2 or row[1] is None:
                continue
            out.append(Event(
                "smard", name,
                datetime.fromtimestamp(row[0] / 1000.0, tz=timezone.utc),
                available_at, float(row[1]), unit,
            ))
        return out

    async def latest_many(self, specs, fetched_at=None):
        fetched_at = _utc(fetched_at or datetime.now(timezone.utc))
        tasks = [self.latest_events(name, unit, fetched_at) for name, unit in specs]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        out = []
        for block in results:
            if isinstance(block, Exception):
                continue
            out.extend(block)
        return out


class OpenMeteoRunClient:
    BASE = "https://single-runs-api.open-meteo.com/v1/forecast"

    def __init__(self, fetch_json):
        self.fetch_json = fetch_json

    @staticmethod
    def run_url(latitude, longitude, run_at, hourly, model=None, forecast_hours=72):
        run_at = _utc(run_at)
        params = {
            "latitude": "%.5f" % float(latitude),
            "longitude": "%.5f" % float(longitude),
            "run": run_at.strftime("%Y-%m-%dT%H:%M"),
            "hourly": ",".join(hourly),
            "forecast_hours": int(forecast_hours),
            "timezone": "UTC",
            "wind_speed_unit": "ms",
        }
        if model:
            params["models"] = model
        return OpenMeteoRunClient.BASE + "?" + urlencode(params)

    def events(self, latitude, longitude, run_at, variables,
               model=None, forecast_hours=72, dissemination_lag_hours=3.0):
        run_at = _utc(run_at)
        payload = self.fetch_json(self.run_url(
            latitude, longitude, run_at, variables, model=model,
            forecast_hours=forecast_hours,
        ))
        available_at = run_at + timedelta(hours=float(dissemination_lag_hours))
        hourly = payload.get("hourly", {})
        times = hourly.get("time", [])
        units = payload.get("hourly_units", {})
        out = []
        for variable in variables:
            values = hourly.get(variable, [])
            for i, value in enumerate(values):
                if value is None or i >= len(times):
                    continue
                valid_at = _parse_time(times[i])
                lead = int((valid_at - run_at).total_seconds() // 60)
                out.append(Event(
                    "open_meteo_run", variable, valid_at, available_at,
                    float(value), units.get(variable, ""), run_at, lead,
                ))
        return out


class OpenMeteoForecastClient:
    BASE = "https://api.open-meteo.com/v1/forecast"
    VARIABLES = (
        "temperature_2m", "wind_speed_100m", "wind_direction_100m",
        "shortwave_radiation", "cloud_cover",
    )

    def __init__(self, fetch_json=browser_fetch_json):
        self.fetch_json = fetch_json

    @classmethod
    def url(cls, latitude, longitude, forecast_hours=48):
        params = {
            "latitude": "%.4f" % float(latitude),
            "longitude": "%.4f" % float(longitude),
            "hourly": ",".join(cls.VARIABLES),
            "forecast_hours": int(forecast_hours),
            "timezone": "UTC",
            "wind_speed_unit": "ms",
        }
        return cls.BASE + "?" + urlencode(params)

    async def point(self, name, latitude, longitude, fetched_at=None, forecast_hours=48):
        fetched_at = _utc(fetched_at or datetime.now(timezone.utc))
        payload = await self.fetch_json(self.url(latitude, longitude, forecast_hours))
        hourly = payload.get("hourly", {})
        units = payload.get("hourly_units", {})
        times = hourly.get("time", [])
        rows = []
        for i, raw_time in enumerate(times):
            valid_at = _parse_time(raw_time)
            row = {
                "point": name,
                "latitude": float(latitude),
                "longitude": float(longitude),
                "valid_at": valid_at,
            }
            for variable in self.VARIABLES:
                values = hourly.get(variable, [])
                value = values[i] if i < len(values) else None
                row[variable] = None if value is None else float(value)
                row[variable + "_unit"] = units.get(variable, "")
            rows.append(row)
        return rows

    async def germany(self, fetched_at=None, forecast_hours=48):
        fetched_at = _utc(fetched_at or datetime.now(timezone.utc))
        tasks = [
            self.point(name, lat, lon, fetched_at, forecast_hours)
            for name, lat, lon in GERMANY_WEATHER_POINTS
        ]
        point_rows = await asyncio.gather(*tasks, return_exceptions=True)
        out = {}
        for (name, _, _), rows in zip(GERMANY_WEATHER_POINTS, point_rows):
            if isinstance(rows, Exception):
                continue
            out[name] = rows
        if not out:
            raise RuntimeError("Open-Meteo weather stencil returned no usable points")
        return out

# POARI / DVX — infrastructure upgrade schedule

This document is the promotion path from the current live proof-of-concept to a
reliable, reproducible decision-support runtime. Each stage has an acceptance
gate. A later stage should not erase the evidence from an earlier one.

## Stage 1 — walk-forward backtesting (current)

Goal: make claims falsifiable before adding model complexity.

Deliverables:
- strict decision-time / realization-time separation;
- rolling walk-forward runner;
- p = -1, 0, 1, 2 POARI comparisons;
- causal baselines: HOLD, rolling-price quantile, trend;
- separately labelled hindsight reference;
- forecast MAE/RMSE/direction and interval coverage at 15 min / 1 h / 4 h;
- battery economics with terminal inventory normalization;
- regime slices (price, volatility, residual load, renewable surplus);
- KAN/Hopfield diagnostics;
- trajectory-atlas geometry: effective rank, angular separation, uncertainty
  thickness, loss contrast, failure margin and Haar 1/2/4/8 coefficients.

Gate: unit tests demonstrate future mutation cannot change a decision-time
forecast; report is deterministic for the same tape/config.

## Stage 2 — historical evidence store

Goal: replace the synthetic benchmark with auditable German electricity and
weather history without weakening the anti-hindsight rule.

Deliverables:
- append-only event archive with valid_at, available_at, run_at,
  lead_minutes, source revision and fetch timestamp;
- SMARD historical observations and published forecasts;
- archived weather forecast runs (not today's reforecast of yesterday);
- local compressed cache usable offline in DVX;
- dataset manifest with hashes and missingness statistics;
- replay ranges by exact UTC interval.

Gate: a historical backtest can be rerun offline from a dataset manifest and
produces byte-stable input hashes.

## Stage 3 — model + policy registry

Goal: know exactly what produced every action.

Deliverables:
- immutable model/policy IDs;
- KAN spline coefficients and Hopfield memories serialized with versions;
- configuration hash covering p, horizon, action set, battery and scenario model;
- report links to data hash + code/model hash;
- automatic ablation matrix:
  POARI / no-KAN / no-Hopfield / p-lenses / forecast-only baselines.

Gate: every displayed recommendation can be traced to one data snapshot,
one model state and one config.

## Stage 4 — shadow operations

Goal: run continuously without pretending to control anything.

Deliverables:
- persistent scheduler for fetch -> assimilate -> decide -> record;
- shadow ledger of proposed actions and later realized outcomes;
- restart-safe state and battery simulation;
- stale-data circuit breaker;
- explicit LIVE / DEGRADED / REPLAY / OFFLINE states;
- bounded retries and source-specific backoff.

Gate: seven-day unattended shadow run with no silent gaps and with every
missed/stale interval explicitly represented.

## Stage 5 — observability and reliability

Goal: failures become visible data, not anecdotes.

Deliverables:
- source freshness, latency and missingness series;
- decision latency and memory/runtime budgets;
- forecast calibration drift;
- action churn / basin switching / trajectory-fan drift;
- append-only structured logs;
- exportable incident bundle;
- one-tap rollback to previous DVX runtime/project artifact.

Gate: a forced source outage, malformed update, stale forecast and runtime
restart each produce the expected degraded state and recover without data loss.

## Stage 6 — spatial electric-weather field

Goal: graduate from national aggregates to physically meaningful nodes.

Deliverables:
- weather-model grid/ensemble ingestion;
- TSO/bidding-zone or other defensible electrical spatial aggregation;
- node-to-node uncertainty propagation;
- power/weather graph provenance (no fake localization of national data);
- optional GRIB/NetCDF preprocessing outside the phone, compact field tiles
  inside DVX;
- backtests comparing node density and field resolution.

Gate: spatialization improves held-out forecast/action metrics or is removed.

## Stage 7 — service boundary

Goal: DVX becomes a dependable client of a small reproducible computation
service, while remaining useful offline.

Deliverables:
- typed read-only data/backtest API;
- job IDs and resumable long backtests;
- artifact registry for datasets/reports/models;
- signed/public runtime update channel separated from private source repos;
- compatibility contract between DVX runtime and project artifact.

Gate: phone, desktop and CI reproduce the same report from the same manifest.

## Stage 8 — controlled action interface (only if justified)

Goal: make external actuation possible without letting research code become
an uncontrolled controller.

Deliverables:
- explicit operator approval boundary;
- limits, interlocks and dry-run mode;
- idempotent action requests;
- reconciliation against measured state;
- audit log and emergency disable;
- domain-specific safety review before any physical system integration.

Gate: shadow-mode evidence and failure testing justify moving beyond
decision support.

## Weekly cadence

Each week should ship one small, testable vertical slice:

1. choose one acceptance criterion;
2. implement the narrowest end-to-end path;
3. add regression tests/backtest evidence;
4. publish through the DVX anonymous artifact channel;
5. keep the previous artifact as rollback;
6. record what improved, regressed, or remained unmeasured.

No stage is promoted because of UI polish alone.
